330 :                     int pj = permutation[j];
331 :                     lmDir[pj] = -lmDir[pj];
332 :                     point[pj] = oldX[pj] + lmDir[pj];
333 :                     double s = diag[pj] * lmDir[pj];
334 :                     lmNorm  += s * s;
335 :                 }
336 :                 lmNorm = Math.sqrt(lmNorm);
337 : 
338 :                 // on the first iteration, adjust the initial step bound.
339 :                 if (firstIteration) {
340 :                     delta = Math.min(delta, lmNorm);
341 :                 }
342 : 
343 :                 // evaluate the function at x + p and calculate its norm
344 :                 updateResidualsAndCost();
345 : 
346 :                 // compute the scaled actual reduction
347 :                 double actRed = -1.0;
348 :                 if (0.1 * cost < previousCost) {
349 :                     double r = cost / previousCost;
350 :                     actRed = 1.0 - r * r;
351 :                 }
352 : 
353 :                 // compute the scaled predicted reduction
354 :                 // and the scaled directional derivative
355 :                 for (int j = 0; j < solvedCols; ++j) {
356 :                     int pj = permutation[j];
357 :                     double dirJ = lmDir[pj];
358 :                     work1[j] = 0;
359 :                     for (int i = 0; i <= j; ++i) {
360 :                         work1[i] += jacobian[i][pj] * dirJ;
361 :                     }
362 :                 }
363 :                 double coeff1 = 0;
364 :                 for (int j = 0; j < solvedCols; ++j) {
365 :                     coeff1 += work1[j] * work1[j];
366 :                 }
367 :                 double pc2 = previousCost * previousCost;
368 :                 coeff1 = coeff1 / pc2;
369 :                 double coeff2 = lmPar * lmNorm * lmNorm / pc2;
370 :                 double preRed = coeff1 + 2 * coeff2;
371 :                 double dirDer = -(coeff1 + coeff2);
372 : 
373 :                 // ratio of the actual to the predicted reduction
374 :                 ratio = (preRed == 0) ? 0 : (actRed / preRed);
375 : 
376 :                 // update the step bound
377 :                 if (ratio <= 0.25) {
378 :                     double tmp =
379 :                         (actRed < 0) ? (0.5 * dirDer / (dirDer + 0.5 * actRed)) : 0.5;
380 :                         if ((0.1 * cost >= previousCost) || (tmp < 0.1)) {
381 :                             tmp = 0.1;
382 :                         }
383 :                         delta = tmp * Math.min(delta, 10.0 * lmNorm);
384 :                         lmPar /= tmp;
385 :                 } else if ((lmPar == 0) || (ratio >= 0.75)) {
386 :                     delta = 2 * lmNorm;
387 :                     lmPar *= 0.5;
388 :                 }
389 : 
390 :                 // test for successful iteration.
391 :                 if (ratio >= 1.0e-4) {
392 :                     // successful iteration, update the norm
393 :                     firstIteration = false;
394 :                     xNorm = 0;
395 :                     for (int k = 0; k < cols; ++k) {
396 :                         double xK = diag[k] * point[k];
397 :                         xNorm    += xK * xK;
398 :                     }
399 :                     xNorm = Math.sqrt(xNorm);
400 :                 } else {
401 :                     // failed iteration, reset the previous values
402 :                     cost = previousCost;
403 :                     for (int j = 0; j < solvedCols; ++j) {
404 :                         int pj = permutation[j];
405 :                         point[pj] = oldX[pj];
406 :                     }
407 :                     tmpVec    = residuals;
408 :                     residuals = oldRes;
409 :                     oldRes    = tmpVec;
410 :                 }
411 : 
412 :                 // tests for convergence.
413 :                     // we use the vectorial convergence checker
414 :                     // we use the Levenberg-Marquardt specific convergence parameters
415 :                     if (((Math.abs(actRed) <= costRelativeTolerance) &&
416 :                          (preRed <= costRelativeTolerance) &&
417 :                          (ratio <= 2.0)) ||
418 :                         (delta <= parRelativeTolerance * xNorm)) {
419 :                         return new VectorialPointValuePair(point, objective);
420 :                     }
421 : 
422 :                 // tests for termination and stringent tolerances
423 :                 // (2.2204e-16 is the machine epsilon for IEEE754)
424 :                 if ((Math.abs(actRed) <= 2.2204e-16) && (preRed <= 2.2204e-16) && (ratio <= 2.0)) {
425 :                     throw new OptimizationException("cost relative tolerance is too small ({0})," +
426 :                             " no further reduction in the" +
427 :                             " sum of squares is possible",
428 :                             costRelativeTolerance);
429 :                 } else if (delta <= 2.2204e-16 * xNorm) {
430 :                     throw new OptimizationException("parameters relative tolerance is too small" +
431 :                             " ({0}), no further improvement in" +
432 :                             " the approximate solution is possible",
433 :                             parRelativeTolerance);
434 :                 } else if (maxCosine <= 2.2204e-16)  {
435 :                     throw new OptimizationException("orthogonality tolerance is too small ({0})," +
436 :                             " solution is orthogonal to the jacobian",
437 :                             orthoTolerance);
438 :                 }
439 : 
440 :             }
441 : 
442 :         }
443 : 
444 :     }"

"468 :     private void determineLMParameter(double[] qy, double delta, double[] diag,
469 :             double[] work1, double[] work2, double[] work3) {
470 : 
471 :         // compute and store in x the gauss-newton direction, if the
472 :         // jacobian is rank-deficient, obtain a least squares solution
473 :         for (int j = 0; j < rank; ++j) {
474 :             lmDir[permutation[j]] = qy[j];
475 :         }
476 :         for (int j = rank; j < cols; ++j) {
477 :             lmDir[permutation[j]] = 0;
478 :         }
479 :         for (int k = rank - 1; k >= 0; --k) {
480 :             int pk = permutation[k];
481 :             double ypk = lmDir[pk] / diagR[pk];
482 :             for (int i = 0; i < k; ++i) {
483 :                 lmDir[permutation[i]] -= ypk * jacobian[i][pk];
484 :             }
485 :             lmDir[pk] = ypk;
486 :         }
487 : 
488 :         // evaluate the function at the origin, and test
489 :         // for acceptance of the Gauss-Newton direction
490 :         double dxNorm = 0;
491 :         for (int j = 0; j < solvedCols; ++j) {
492 :             int pj = permutation[j];
493 :             double s = diag[pj] * lmDir[pj];
494 :             work1[pj] = s;
495 :             dxNorm += s * s;
496 :         }
497 :         dxNorm = Math.sqrt(dxNorm);
498 :         double fp = dxNorm - delta;
499 :         if (fp <= 0.1 * delta) {
500 :             lmPar = 0;
501 :             return;
502 :         }
503 : 
504 :         // if the jacobian is not rank deficient, the Newton step provides
505 :         // a lower bound, parl, for the zero of the function,
506 :         // otherwise set this bound to zero
507 :         double sum2;
508 :         double parl = 0;
509 :         if (rank == solvedCols) {
510 :             for (int j = 0; j < solvedCols; ++j) {
511 :                 int pj = permutation[j];
512 :                 work1[pj] *= diag[pj] / dxNorm;
513 :             }
514 :             sum2 = 0;
515 :             for (int j = 0; j < solvedCols; ++j) {
516 :                 int pj = permutation[j];
517 :                 double sum = 0;
518 :                 for (int i = 0; i < j; ++i) {
519 :                     sum += jacobian[i][pj] * work1[permutation[i]];
520 :                 }
521 :                 double s = (work1[pj] - sum) / diagR[pj];
522 :                 work1[pj] = s;
523 :                 sum2 += s * s;
524 :             }
525 :             parl = fp / (delta * sum2);
526 :         }
527 : 
528 :         // calculate an upper bound, paru, for the zero of the function
529 :         sum2 = 0;
530 :         for (int j = 0; j < solvedCols; ++j) {
531 :             int pj = permutation[j];
532 :             double sum = 0;
533 :             for (int i = 0; i <= j; ++i) {
534 :                 sum += jacobian[i][pj] * qy[i];
535 :             }
536 :             sum /= diag[pj];
537 :             sum2 += sum * sum;
538 :         }
539 :         double gNorm = Math.sqrt(sum2);
540 :         double paru = gNorm / delta;
541 :         if (paru == 0) {
542 :             // 2.2251e-308 is the smallest positive real for IEE754
543 :             paru = 2.2251e-308 / Math.min(delta, 0.1);
544 :         }
545 : 
546 :         // if the input par lies outside of the interval (parl,paru),
547 :         // set par to the closer endpoint
548 :         lmPar = Math.min(paru, Math.max(lmPar, parl));
549 :         if (lmPar == 0) {
550 :             lmPar = gNorm / dxNorm;
551 :         }
552 : 
553 :         for (int countdown = 10; countdown >= 0; --countdown) {
554 : 
555 :             // evaluate the function at the current value of lmPar
556 :             if (lmPar == 0) {
557 :                 lmPar = Math.max(2.2251e-308, 0.001 * paru);
558 :             }
559 :             double sPar = Math.sqrt(lmPar);
560 :             for (int j = 0; j < solvedCols; ++j) {
561 :                 int pj = permutation[j];
562 :                 work1[pj] = sPar * diag[pj];
563 :             }
564 :             determineLMDirection(qy, work1, work2, work3);
565 : 
566 :             dxNorm = 0;
567 :             for (int j = 0; j < solvedCols; ++j) {
568 :                 int pj = permutation[j];
569 :                 double s = diag[pj] * lmDir[pj];
570 :                 work3[pj] = s;
571 :                 dxNorm += s * s;
572 :             }
573 :             dxNorm = Math.sqrt(dxNorm);
574 :             double previousFP = fp;
575 :             fp = dxNorm - delta;
576 : 
577 :             // if the function is small enough, accept the current value
578 :             // of lmPar, also test for the exceptional cases where parl is zero
579 :             if ((Math.abs(fp) <= 0.1 * delta) ||
580 :                     ((parl == 0) && (fp <= previousFP) && (previousFP < 0))) {
581 :                 return;
582 :             }
583 : 
584 :             // compute the Newton correction
585 :             for (int j = 0; j < solvedCols; ++j) {
586 :                 int pj = permutation[j];
587 :                 work1[pj] = work3[pj] * diag[pj] / dxNorm;
588 :             }
589 :             for (int j = 0; j < solvedCols; ++j) {
590 :                 int pj = permutation[j];
591 :                 work1[pj] /= work2[j];
592 :                 double tmp = work1[pj];
593 :                 for (int i = j + 1; i < solvedCols; ++i) {
594 :                     work1[permutation[i]] -= jacobian[i][pj] * tmp;
595 :                 }
596 :             }
597 :             sum2 = 0;
598 :             for (int j = 0; j < solvedCols; ++j) {
599 :                 double s = work1[permutation[j]];
600 :                 sum2 += s * s;
601 :             }
602 :             double correction = fp / (delta * sum2);
603 : 
604 :             // depending on the sign of the function, update parl or paru.
605 :             if (fp > 0) {
606 :                 parl = Math.max(parl, lmPar);
607 :             } else if (fp < 0) {
608 :                 paru = Math.min(paru, lmPar);
609 :             }
610 : 
611 :             // compute an improved estimate for lmPar
612 :             lmPar = Math.max(parl, lmPar + correction);
613 : 
614 :         }
615 :     }"

"204 :     protected void updateResidualsAndCost()
205 :         throws FunctionEvaluationException {
206 : 
207 :         if (++objectiveEvaluations > maxEvaluations) {
208 :             throw new FunctionEvaluationException(new MaxEvaluationsExceededException(maxEvaluations),
209 :                                                   point);
210 :         }
211 :         objective = function.value(point);
212 :         if (objective.length != rows) {
213 :             throw new FunctionEvaluationException(point, "dimension mismatch {0} != {1}",
214 :                                                   objective.length, rows);
215 :         }
216 :         cost = 0;
217 :         int index = 0;
218 :         for (int i = 0; i < rows; i++) {
219 :             final double residual = targetValues[i] - objective[i];
220 :             residuals[i] = residual;
221 :             cost += residualsWeights[i] * residual * residual;
222 :             index += cols;
223 :         }
224 :         cost = Math.sqrt(cost);
225 : 
226 :     }"

"324 :     public VectorialPointValuePair optimize(final DifferentiableMultivariateVectorialFunction f,
325 :                                             final double[] target, final double[] weights,
326 :                                             final double[] startPoint)
327 :         throws FunctionEvaluationException, OptimizationException, IllegalArgumentException {
328 : 
329 :         if (target.length != weights.length) {
330 :             throw new OptimizationException("dimension mismatch {0} != {1}",
331 :                                             target.length, weights.length);
332 :         }
333 : 
334 :         // reset counters
335 :         iterations           = 0;
336 :         objectiveEvaluations = 0;
337 :         jacobianEvaluations  = 0;
338 : 
339 :         // store least squares problem characteristics
340 :         function         = f;
341 :         jF               = f.jacobian();
342 :         targetValues     = target.clone();
343 :         residualsWeights = weights.clone();
344 :         this.point       = startPoint.clone();
345 :         this.residuals   = new double[target.length];
346 : 
347 :         // arrays shared with the other private methods
348 :         rows      = target.length;
349 :         cols      = point.length;
350 :         jacobian  = new double[rows][cols];
351 : 
352 :         cost = Double.POSITIVE_INFINITY;
353 : 
354 :         return doOptimize();
355 : 
356 :     }"

"182 :     protected void updateJacobian() throws FunctionEvaluationException {
183 :         ++jacobianEvaluations;
184 :         jacobian = jF.value(point);
185 :         if (jacobian.length != rows) {
186 :             throw new FunctionEvaluationException(point, "dimension mismatch {0} != {1}",
187 :                                                   jacobian.length, rows);
188 :         }
189 :         for (int i = 0; i < rows; i++) {
190 :             final double[] ji = jacobian[i];
191 :             final double factor = -Math.sqrt(residualsWeights[i]);
192 :             for (int j = 0; j < cols; ++j) {
193 :                 ji[j] *= factor;
194 :             }
195 :         }
196 :     }"

"763 :     private void qrDecomposition() throws OptimizationException {
764 : 
765 :         // initializations
766 :         for (int k = 0; k < cols; ++k) {
767 :             permutation[k] = k;
768 :             double norm2 = 0;
769 :             for (int i = 0; i < jacobian.length; ++i) {
770 :                 double akk = jacobian[i][k];
771 :                 norm2 += akk * akk;
772 :             }
773 :             jacNorm[k] = Math.sqrt(norm2);
774 :         }
775 : 
776 :         // transform the matrix column after column
777 :         for (int k = 0; k < cols; ++k) {
778 : 
779 :             // select the column with the greatest norm on active components
780 :             int nextColumn = -1;
781 :             double ak2 = Double.NEGATIVE_INFINITY;
782 :             for (int i = k; i < cols; ++i) {
783 :                 double norm2 = 0;
784 :                 for (int j = k; j < jacobian.length; ++j) {
785 :                     double aki = jacobian[j][permutation[i]];
786 :                     norm2 += aki * aki;
787 :                 }
788 :                 if (Double.isInfinite(norm2) || Double.isNaN(norm2)) {
789 :                     throw new OptimizationException(
790 :                             "unable to perform Q.R decomposition on the {0}x{1} jacobian matrix",
791 :                             rows, cols);
792 :                 }
793 :                 if (norm2 > ak2) {
794 :                     nextColumn = i;
795 :                     ak2        = norm2;
796 :                 }
797 :             }
798 :             if (ak2 == 0) {
799 :                 rank = k;
800 :                 return;
801 :             }
802 :             int pk                  = permutation[nextColumn];
803 :             permutation[nextColumn] = permutation[k];
804 :             permutation[k]          = pk;
805 : 
806 :             // choose alpha such that Hk.u = alpha ek
807 :             double akk   = jacobian[k][pk];
808 :             double alpha = (akk > 0) ? -Math.sqrt(ak2) : Math.sqrt(ak2);
809 :             double betak = 1.0 / (ak2 - akk * alpha);
810 :             beta[pk]     = betak;
811 : 
812 :             // transform the current column
813 :             diagR[pk]        = alpha;
814 :             jacobian[k][pk] -= alpha;
815 : 
816 :             // transform the remaining columns
817 :             for (int dk = cols - 1 - k; dk > 0; --dk) {
818 :                 double gamma = 0;
819 :                 for (int j = k; j < jacobian.length; ++j) {
820 :                     gamma += jacobian[j][pk] * jacobian[j][permutation[k + dk]];
821 :                 }
822 :                 gamma *= betak;
823 :                 for (int j = k; j < jacobian.length; ++j) {
824 :                     jacobian[j][permutation[k + dk]] -= gamma * jacobian[j][pk];
825 :                 }
826 :             }
827 : 
828 :         }
829 : 
830 :         rank = solvedCols;
831 : 
832 :     }"

"839 :     private void qTy(double[] y) {
840 :         for (int k = 0; k < cols; ++k) {
841 :             int pk = permutation[k];
842 :             double gamma = 0;
843 :             for (int i = k; i < rows; ++i) {
844 :                 gamma += jacobian[i][pk] * y[i];
845 :             }
846 :             gamma *= beta[pk];
847 :             for (int i = k; i < rows; ++i) {
848 :                 y[i] -= gamma * jacobian[i][pk];
849 :             }
850 :         }
851 :     }"

"637 :     private void determineLMDirection(double[] qy, double[] diag,
638 :             double[] lmDiag, double[] work) {
639 : 
640 :         // copy R and Qty to preserve input and initialize s
641 :         //  in particular, save the diagonal elements of R in lmDir
642 :         for (int j = 0; j < solvedCols; ++j) {
643 :             int pj = permutation[j];
644 :             for (int i = j + 1; i < solvedCols; ++i) {
645 :                 jacobian[i][pj] = jacobian[j][permutation[i]];
646 :             }
647 :             lmDir[j] = diagR[pj];
648 :             work[j]  = qy[j];
649 :         }
650 : 
651 :         // eliminate the diagonal matrix d using a Givens rotation
652 :         for (int j = 0; j < solvedCols; ++j) {
653 : 
654 :             // prepare the row of d to be eliminated, locating the
655 :             // diagonal element using p from the Q.R. factorization
656 :             int pj = permutation[j];
657 :             double dpj = diag[pj];
658 :             if (dpj != 0) {
659 :                 Arrays.fill(lmDiag, j + 1, lmDiag.length, 0);
660 :             }
661 :             lmDiag[j] = dpj;
662 : 
663 :             //  the transformations to eliminate the row of d
664 :             // modify only a single element of Qty
665 :             // beyond the first n, which is initially zero.
666 :             double qtbpj = 0;
667 :             for (int k = j; k < solvedCols; ++k) {
668 :                 int pk = permutation[k];
669 : 
670 :                 // determine a Givens rotation which eliminates the
671 :                 // appropriate element in the current row of d
672 :                 if (lmDiag[k] != 0) {
673 : 
674 :                     final double sin;
675 :                     final double cos;
676 :                     double rkk = jacobian[k][pk];
677 :                     if (Math.abs(rkk) < Math.abs(lmDiag[k])) {
678 :                         final double cotan = rkk / lmDiag[k];
679 :                         sin   = 1.0 / Math.sqrt(1.0 + cotan * cotan);
680 :                         cos   = sin * cotan;
681 :                     } else {
682 :                         final double tan = lmDiag[k] / rkk;
683 :                         cos = 1.0 / Math.sqrt(1.0 + tan * tan);
684 :                         sin = cos * tan;
685 :                     }
686 : 
687 :                     // compute the modified diagonal element of R and
688 :                     // the modified element of (Qty,0)
689 :                     jacobian[k][pk] = cos * rkk + sin * lmDiag[k];
690 :                     final double temp = cos * work[k] + sin * qtbpj;
691 :                     qtbpj = -sin * work[k] + cos * qtbpj;
692 :                     work[k] = temp;
693 : 
694 :                     // accumulate the tranformation in the row of s
695 :                     for (int i = k + 1; i < solvedCols; ++i) {
696 :                         double rik = jacobian[i][pk];
697 :                         final double temp2 = cos * rik + sin * lmDiag[i];
698 :                         lmDiag[i] = -sin * rik + cos * lmDiag[i];
699 :                         jacobian[i][pk] = temp2;
700 :                     }
701 : 
702 :                 }
703 :             }
704 : 
705 :             // store the diagonal element of s and restore
706 :             // the corresponding diagonal element of R
707 :             lmDiag[j] = jacobian[j][permutation[j]];
708 :             jacobian[j][permutation[j]] = lmDir[j];
709 : 
710 :         }
711 : 
712 :         // solve the triangular system for z, if the system is
713 :         // singular, then obtain a least squares solution
714 :         int nSing = solvedCols;
715 :         for (int j = 0; j < solvedCols; ++j) {
716 :             if ((lmDiag[j] == 0) && (nSing == solvedCols)) {
717 :                 nSing = j;
718 :             }
719 :             if (nSing < solvedCols) {
720 :                 work[j] = 0;
721 :             }
722 :         }
723 :         if (nSing > 0) {
724 :             for (int j = nSing - 1; j >= 0; --j) {
725 :                 int pj = permutation[j];
726 :                 double sum = 0;
727 :                 for (int i = j + 1; i < nSing; ++i) {
728 :                     sum += jacobian[i][pj] * work[i];
729 :                 }
730 :                 work[j] = (work[j] - sum) / lmDiag[j];
731 :             }
732 :         }
733 : 
734 :         // permute the components of z back to components of lmDir
735 :         for (int j = 0; j < lmDir.length; ++j) {
736 :             lmDir[permutation[j]] = work[j];
737 :         }
738 : 
739 :     }"

