"219 :     @Override
220 :     protected VectorialPointValuePair doOptimize()
221 :         throws FunctionEvaluationException, OptimizationException, IllegalArgumentException {
222 : 
223 :         // arrays shared with the other private methods
224 :         solvedCols  = Math.min(rows, cols);
225 :         diagR       = new double[cols];
226 :         jacNorm     = new double[cols];
227 :         beta        = new double[cols];
228 :         permutation = new int[cols];
229 :         lmDir       = new double[cols];
230 : 
231 :         // local point
232 :         double   delta   = 0;
233 :         double   xNorm   = 0;
234 :         double[] diag    = new double[cols];
235 :         double[] oldX    = new double[cols];
236 :         double[] oldRes  = new double[rows];
237 :         double[] work1   = new double[cols];
238 :         double[] work2   = new double[cols];
239 :         double[] work3   = new double[cols];
240 : 
241 :         // evaluate the function at the starting point and calculate its norm
242 :         updateResidualsAndCost();
243 : 
244 :         // outer loop
245 :         lmPar = 0;
246 :         boolean firstIteration = true;
247 :         while (true) {
248 : 
249 :             incrementIterationsCounter();
250 : 
251 :             // compute the Q.R. decomposition of the jacobian matrix
252 :             updateJacobian();
253 :             qrDecomposition();
254 : 
255 :             // compute Qt.res
256 :             qTy(residuals);
257 : 
258 :             // now we don't need Q anymore,
259 :             // so let jacobian contain the R matrix with its diagonal elements
260 :             for (int k = 0; k < solvedCols; ++k) {
261 :                 int pk = permutation[k];
262 :                 jacobian[k][pk] = diagR[pk];
263 :             }
264 : 
265 :             if (firstIteration) {
266 : 
267 :                 // scale the point according to the norms of the columns
268 :                 // of the initial jacobian
269 :                 xNorm = 0;
270 :                 for (int k = 0; k < cols; ++k) {
271 :                     double dk = jacNorm[k];
272 :                     if (dk == 0) {
273 :                         dk = 1.0;
274 :                     }
275 :                     double xk = dk * point[k];
276 :                     xNorm  += xk * xk;
277 :                     diag[k] = dk;
278 :                 }
279 :                 xNorm = Math.sqrt(xNorm);
280 : 
281 :                 // initialize the step bound delta
282 :                 delta = (xNorm == 0) ? initialStepBoundFactor : (initialStepBoundFactor * xNorm);
283 : 
284 :             }
285 : 
286 :             // check orthogonality between function vector and jacobian columns
287 :             double maxCosine = 0;
288 :             if (cost != 0) {
289 :                 for (int j = 0; j < solvedCols; ++j) {
290 :                     int    pj = permutation[j];
291 :                     double s  = jacNorm[pj];
292 :                     if (s != 0) {
293 :                         double sum = 0;
294 :                         for (int i = 0; i <= j; ++i) {
295 :                             sum += jacobian[i][pj] * residuals[i];
296 :                         }
297 :                         maxCosine = Math.max(maxCosine, Math.abs(sum) / (s * cost));
298 :                     }
299 :                 }
300 :             }
301 :             if (maxCosine <= orthoTolerance) {
302 :                 // convergence has been reached
303 :                 return new VectorialPointValuePair(point, objective);
304 :             }
305 : 
306 :             // rescale if necessary
307 :             for (int j = 0; j < cols; ++j) {
308 :                 diag[j] = Math.max(diag[j], jacNorm[j]);
309 :             }
310 : 
311 :             // inner loop
312 :             for (double ratio = 0; ratio < 1.0e-4;) {
313 : 
314 :                 // save the state
315 :                 for (int j = 0; j < solvedCols; ++j) {
316 :                     int pj = permutation[j];
317 :                     oldX[pj] = point[pj];
318 :                 }
319 :                 double previousCost = cost;
320 :                 double[] tmpVec = residuals;
321 :                 residuals = oldRes;
322 :                 oldRes    = tmpVec;
323 : 
324 :                 // determine the Levenberg-Marquardt parameter
325 :                 determineLMParameter(oldRes, delta, diag, work1, work2, work3);
326 : 
327 :                 // compute the new point and the norm of the evolution direction
328 :                 double lmNorm = 0;
329 :                 for (int j = 0; j < solvedCols; ++j) {
330 :                     int pj = permutation[j];
331 :                     lmDir[pj] = -lmDir[pj];
332 :                     point[pj] = oldX[pj] + lmDir[pj];
333 :                     double s = diag[pj] * lmDir[pj];
334 :                     lmNorm  += s * s;
335 :                 }
336 :                 lmNorm = Math.sqrt(lmNorm);
337 : 
338 :                 // on the first iteration, adjust the initial step bound.
339 :                 if (firstIteration) {
340 :                     delta = Math.min(delta, lmNorm);
341 :                 }
342 : 
343 :                 // evaluate the function at x + p and calculate its norm
344 :                 updateResidualsAndCost();
345 : 
346 :                 // compute the scaled actual reduction
347 :                 double actRed = -1.0;
348 :                 if (0.1 * cost < previousCost) {
349 :                     double r = cost / previousCost;
350 :                     actRed = 1.0 - r * r;
351 :                 }
352 : 
353 :                 // compute the scaled predicted reduction
354 :                 // and the scaled directional derivative
355 :                 for (int j = 0; j < solvedCols; ++j) {
356 :                     int pj = permutation[j];
357 :                     double dirJ = lmDir[pj];
358 :                     work1[j] = 0;
359 :                     for (int i = 0; i <= j; ++i) {
360 :                         work1[i] += jacobian[i][pj] * dirJ;
361 :                     }
362 :                 }
363 :                 double coeff1 = 0;
364 :                 for (int j = 0; j < solvedCols; ++j) {
365 :                     coeff1 += work1[j] * work1[j];
366 :                 }
367 :                 double pc2 = previousCost * previousCost;
368 :                 coeff1 = coeff1 / pc2;
369 :                 double coeff2 = lmPar * lmNorm * lmNorm / pc2;
370 :                 double preRed = coeff1 + 2 * coeff2;
371 :                 double dirDer = -(coeff1 + coeff2);
372 : 
373 :                 // ratio of the actual to the predicted reduction
374 :                 ratio = (preRed == 0) ? 0 : (actRed / preRed);
375 : 
376 :                 // update the step bound
377 :                 if (ratio <= 0.25) {
378 :                     double tmp =
379 :                         (actRed < 0) ? (0.5 * dirDer / (dirDer + 0.5 * actRed)) : 0.5;
380 :                         if ((0.1 * cost >= previousCost) || (tmp < 0.1)) {
381 :                             tmp = 0.1;
382 :                         }
383 :                         delta = tmp * Math.min(delta, 10.0 * lmNorm);
384 :                         lmPar /= tmp;
385 :                 } else if ((lmPar == 0) || (ratio >= 0.75)) {
386 :                     delta = 2 * lmNorm;
387 :                     lmPar *= 0.5;
388 :                 }
389 : 
390 :                 // test for successful iteration.
391 :                 if (ratio >= 1.0e-4) {
392 :                     // successful iteration, update the norm
393 :                     firstIteration = false;
394 :                     xNorm = 0;
395 :                     for (int k = 0; k < cols; ++k) {
396 :                         double xK = diag[k] * point[k];
397 :                         xNorm    += xK * xK;
398 :                     }
399 :                     xNorm = Math.sqrt(xNorm);
400 :                 } else {
401 :                     // failed iteration, reset the previous values
402 :                     cost = previousCost;
403 :                     for (int j = 0; j < solvedCols; ++j) {
404 :                         int pj = permutation[j];
405 :                         point[pj] = oldX[pj];
406 :                     }
407 :                     tmpVec    = residuals;
408 :                     residuals = oldRes;
409 :                     oldRes    = tmpVec;
410 :                 }
411 : 
412 :                 // tests for convergence.
413 :                     // we use the vectorial convergence checker
414 :                     // we use the Levenberg-Marquardt specific convergence parameters
415 :                     if (((Math.abs(actRed) <= costRelativeTolerance) &&
416 :                          (preRed <= costRelativeTolerance) &&
417 :                          (ratio <= 2.0)) ||
418 :                         (delta <= parRelativeTolerance * xNorm)) {
419 :                         return new VectorialPointValuePair(point, objective);
420 :                     }
421 : 
422 :                 // tests for termination and stringent tolerances
423 :                 // (2.2204e-16 is the machine epsilon for IEEE754)
424 :                 if ((Math.abs(actRed) <= 2.2204e-16) && (preRed <= 2.2204e-16) && (ratio <= 2.0)) {
425 :                     throw new OptimizationException("cost relative tolerance is too small ({0})," +
426 :                             " no further reduction in the" +
427 :                             " sum of squares is possible",
428 :                             costRelativeTolerance);
429 :                 } else if (delta <= 2.2204e-16 * xNorm) {
430 :                     throw new OptimizationException("parameters relative tolerance is too small" +
431 :                             " ({0}), no further improvement in" +
432 :                             " the approximate solution is possible",
433 :                             parRelativeTolerance);
434 :                 } else if (maxCosine <= 2.2204e-16)  {
435 :                     throw new OptimizationException("orthogonality tolerance is too small ({0})," +
436 :                             " solution is orthogonal to the jacobian",
437 :                             orthoTolerance);
438 :                 }
439 : 
440 :             }
441 : 
442 :         }
443 : 
444 :     }"

