"637 :     private void determineLMDirection(double[] qy, double[] diag,
638 :             double[] lmDiag, double[] work) {
639 : 
640 :         // copy R and Qty to preserve input and initialize s
641 :         //  in particular, save the diagonal elements of R in lmDir
642 :         for (int j = 0; j < solvedCols; ++j) {
643 :             int pj = permutation[j];
644 :             for (int i = j + 1; i < solvedCols; ++i) {
645 :                 jacobian[i][pj] = jacobian[j][permutation[i]];
646 :             }
647 :             lmDir[j] = diagR[pj];
648 :             work[j]  = qy[j];
649 :         }
650 : 
651 :         // eliminate the diagonal matrix d using a Givens rotation
652 :         for (int j = 0; j < solvedCols; ++j) {
653 : 
654 :             // prepare the row of d to be eliminated, locating the
655 :             // diagonal element using p from the Q.R. factorization
656 :             int pj = permutation[j];
657 :             double dpj = diag[pj];
658 :             if (dpj != 0) {
659 :                 Arrays.fill(lmDiag, j + 1, lmDiag.length, 0);
660 :             }
661 :             lmDiag[j] = dpj;
662 : 
663 :             //  the transformations to eliminate the row of d
664 :             // modify only a single element of Qty
665 :             // beyond the first n, which is initially zero.
666 :             double qtbpj = 0;
667 :             for (int k = j; k < solvedCols; ++k) {
668 :                 int pk = permutation[k];
669 : 
670 :                 // determine a Givens rotation which eliminates the
671 :                 // appropriate element in the current row of d
672 :                 if (lmDiag[k] != 0) {
673 : 
674 :                     final double sin;
675 :                     final double cos;
676 :                     double rkk = jacobian[k][pk];
677 :                     if (Math.abs(rkk) < Math.abs(lmDiag[k])) {
678 :                         final double cotan = rkk / lmDiag[k];
679 :                         sin   = 1.0 / Math.sqrt(1.0 + cotan * cotan);
680 :                         cos   = sin * cotan;
681 :                     } else {
682 :                         final double tan = lmDiag[k] / rkk;
683 :                         cos = 1.0 / Math.sqrt(1.0 + tan * tan);
684 :                         sin = cos * tan;
685 :                     }
686 : 
687 :                     // compute the modified diagonal element of R and
688 :                     // the modified element of (Qty,0)
689 :                     jacobian[k][pk] = cos * rkk + sin * lmDiag[k];
690 :                     final double temp = cos * work[k] + sin * qtbpj;
691 :                     qtbpj = -sin * work[k] + cos * qtbpj;
692 :                     work[k] = temp;
693 : 
694 :                     // accumulate the tranformation in the row of s
695 :                     for (int i = k + 1; i < solvedCols; ++i) {
696 :                         double rik = jacobian[i][pk];
697 :                         final double temp2 = cos * rik + sin * lmDiag[i];
698 :                         lmDiag[i] = -sin * rik + cos * lmDiag[i];
699 :                         jacobian[i][pk] = temp2;
700 :                     }
701 : 
702 :                 }
703 :             }
704 : 
705 :             // store the diagonal element of s and restore
706 :             // the corresponding diagonal element of R
707 :             lmDiag[j] = jacobian[j][permutation[j]];
708 :             jacobian[j][permutation[j]] = lmDir[j];
709 : 
710 :         }
711 : 
712 :         // solve the triangular system for z, if the system is
713 :         // singular, then obtain a least squares solution
714 :         int nSing = solvedCols;
715 :         for (int j = 0; j < solvedCols; ++j) {
716 :             if ((lmDiag[j] == 0) && (nSing == solvedCols)) {
717 :                 nSing = j;
718 :             }
719 :             if (nSing < solvedCols) {
720 :                 work[j] = 0;
721 :             }
722 :         }
723 :         if (nSing > 0) {
724 :             for (int j = nSing - 1; j >= 0; --j) {
725 :                 int pj = permutation[j];
726 :                 double sum = 0;
727 :                 for (int i = j + 1; i < nSing; ++i) {
728 :                     sum += jacobian[i][pj] * work[i];
729 :                 }
730 :                 work[j] = (work[j] - sum) / lmDiag[j];
731 :             }
732 :         }
733 : 
734 :         // permute the components of z back to components of lmDir
735 :         for (int j = 0; j < lmDir.length; ++j) {
736 :             lmDir[permutation[j]] = work[j];
737 :         }
738 : 
739 :     }"
